// ── 👥 invitacion-multi · el que llega por invitación entra YA en multijugador ──────────────────
//
// EL HUECO QUE TAPA (comprobado 2026-09-03): `server.py` da escritura a quien llega con
// `?invita=<vale>` (server.py:1466) y el árbitro del 8510 sabe entrar con ese vale en el
// subprotocolo… pero EN EL NAVEGADOR NADIE ARRANCA EL CLIENTE. `multi-verse` acaba en
// `tomaValeDeLaUrl(); entra();`, o sea que se conecta solo EN CUANTO SE CARGA — y hoy solo lo
// carga `mundo-multiverse`. Resultado: el invitado abre el enlace, puede construir… y no ve a
// nadie ni nadie le ve, que es peor que un error porque parece que funciona.
//
// Y de paso EL RELEVO: `multi-verse` deja `vf_multi_relevo` en sessionStorage al hacer
// `game.multi.join(<otro mapa>)` y su comentario dice «quien recoge el relevo es
// mundo-autoarranque» — pero `mundo-autoarranque` no menciona el relevo por ninguna parte. Sin
// recogerlo, saltar de mundo te deja DESCONECTADO al otro lado.
//
// DOS DISPARADORES, y ninguno más (no conectar a la gente que no lo pidió):
//   1. la URL trae `?invita=` → me han invitado a ESTE mapa
//   2. hay relevo fresco (< PLAZO_MS) → venía jugando y acabo de saltar de mundo
// Si `multi-verse` ya está puesto (`game.multi`), no se toca nada: él solo sabe reconectar.
//
// ⚠️ El vale NO se lee ni se borra aquí: lo hace `tomaValeDeLaUrl()` dentro de `multi-verse`
// (guarda por mapa en sessionStorage y lo quita de la barra). Duplicarlo aquí sería la segunda
// idea de qué es un vale, y el día que cambie el formato una de las dos se queda vieja.
(async () => {
  const PLAZO_MS = 3 * 60 * 1000;          // relevo de hace más de 3 min: ya no reconecta
  const LLAVE_RELEVO = 'vf_multi_relevo';  // la MISMA que escribe multi-verse (no la cambies aquí solo)

  if (typeof game === 'undefined' || !game.snippet) return;
  if (game.multi) return 'multi ya estaba puesto';   // no se apila: él sabe reconectar

  let porInvitacion = false, porRelevo = false;
  try {
    porInvitacion = !!new URLSearchParams(location.search || '').get('invita');
  } catch (e) {}
  try {
    const r = JSON.parse(sessionStorage.getItem(LLAVE_RELEVO) || 'null');
    if (r && r.cuando && (Date.now() - r.cuando) < PLAZO_MS) porRelevo = true;
    // El relevo se consume SIEMPRE que se mire, fresco o rancio: si no, un salto viejo te
    // reconectaría en cada recarga de esa pestaña sin que nadie lo haya pedido.
    if (r) sessionStorage.removeItem(LLAVE_RELEVO);
  } catch (e) {}

  if (!porInvitacion && !porRelevo) return 'sin invitación ni relevo: multi no se arranca';

  try {
    await game.snippet('multi-verse');     // él lee el vale y llama a entra() al final
    if (typeof toast === 'function')
      toast(porInvitacion ? '👥 invitación: entrando en multijugador…'
                          : '👥 reconectando en este mundo…', 4);
    return 'multi-verse arrancado por ' + (porInvitacion ? 'invitación' : 'relevo');
  } catch (e) {
    console.warn('👥 invitacion-multi: no pude arrancar multi-verse:', e && e.message);
    if (typeof toast === 'function') toast('👥 no pude entrar en multijugador: ' + (e && e.message), 6);
    return 'fallo: ' + (e && e.message);
  }
})();
